const SOURCES: readonly StateGeneralSource[] = [
  {
    id: CANVASS,
    url: "https://sdsos.gov/elections-voting/upcoming-elections/general-information/2026%20Election%20Assets/Primary/State%20Canvass%20and%20Certificate.pdf",
    path: "data/source/rapid/state-primary/sd/2026-primary-state-canvass.pdf",
    cycleYear: 2026,
    electionDate: "2026-06-02",
    note: "State Canvassing Board's certified canvass (scan): 3 statewide, 23 Senate and 27 House contested primaries, from a reviewed transcription.",
    transcription: true,
  },
  {
    id: CANDIDATE_LIST,
    url: "https://vip.sdsos.gov/candidatelist.aspx?eid=773",
    path: "data/source/rapid/state-primary/sd/2026-primary-candidate-list.csv",
    cycleYear: 2026,
    electionDate: "2026-06-02",
    note: "Secretary of State's official primary candidate list (CSV export by postback), read for unopposed nominations.",
    postBody: new URLSearchParams({
      __EVENTTARGET: "ctl00$MainContent$grdCandidates$ctl00$ctl02$ctl00$ExportToCsvButton",
      __VIEWSTATE: VIEWSTATE,
      __VIEWSTATEGENERATOR: "E0DD8FE6",
      __EVENTVALIDATION: "",
    }).toString(),
  },
];

type Office = RawPrimaryContest["office"];
const fail = (code: string): never => { throw new Error(`SOUTH_DAKOTA_PRIMARY_${code}`); };
const TRANSCRIPTION_HEADER = "page\toffice\tdistrict\tparty\tcandidate\tvotes";
const OFFICES: Readonly<Record<string, Office>> = { "United States Senator": "us_senate", "United States Representative": "us_house", Governor: "governor", "State Senator": "state_upper", "State Representative": "state_lower" };
const seatsOf = (office: Office, district: string | null): number => office === "state_lower" && /^\d+$/.test(district ?? "") ? 2 : 1;
const key = (office: Office, district: string | null, party: string): string => `${office}|${district ?? ""}|${party}`;

function parseCanvass(text: string): RawPrimaryContest[] {
  const lines = text.split("\n").filter((line) => line !== "");
  if (lines[0] !== TRANSCRIPTION_HEADER) fail("TRANSCRIPTION_HEADER");
  const contests = new Map<string, RawPrimaryContest & { candidates: { name: string; votes: number }[] }>();
  for (const line of lines.slice(1)) {
    const [page, office, district, party, name, votes, extra] = line.split("\t");
    if (extra !== undefined || !/^(?:[4689]|1[0-2])$/.test(page ?? "") || !Object.values(OFFICES).includes(office as Office)) fail(`ROW:${line}`);
    if (!/^(?:REP|DEM)$/.test(party ?? "") || !name || !/^\d+$/.test(votes ?? "") || !/^(?:|AL|\d{1,2}[AB]?)$/.test(district ?? "")) fail(`ROW:${line}`);
    const where = office === "us_senate" || office === "governor" ? null : district!;
    const entry = contests.get(key(office as Office, where, party!)) ?? { office: office as Office, district: where, rawParty: party!, seats: seatsOf(office as Office, where), candidates: [] };
    entry.candidates.push({ name: name!, votes: Number(votes) });
    contests.set(key(office as Office, where, party!), entry);
  }
  return [...contests.values()];
}

function parseCandidateList(text: string, contested: ReadonlySet<string>): RawPrimaryContest[] {
  const [header, ...rows] = parseCsv(text.replace(/^﻿/, ""));
  if (header?.slice(0, 5).join("|") !== "Contest|Name|Party|Petition Filing Date|District/County") fail("CANDIDATE_LIST_HEADER");
  const groups = new Map<string, { office: Office; district: string | null; party: string; names: string[] }>();
  for (const row of rows) {
    const office = OFFICES[row[0] ?? ""], party = row[2] ?? "";
    if (!office || (party !== "REP" && party !== "DEM")) continue;
    const name = (row[1] ?? "").replace(/\s+/g, " ").trim();
    if (/\((?:Withdrawn|Successful Challenge)\b/.test(name)) continue;
    let district: string | null = null;
    if (office === "us_house") district = "AL";
    else if (office === "state_upper" || office === "state_lower") {
      const match = (row[4] ?? "").match(/^District 0*(\d+)([AB]?)$/) ?? fail(`DISTRICT:${row[4]}`);
      district = `${match[1]}${match[2]}`;
    }
    const entry = groups.get(key(office, district, party)) ?? { office, district, party, names: [] };
    entry.names.push(name);
    groups.set(key(office, district, party), entry);
  }
  return [...groups.entries()].flatMap(([groupKey, group]): RawPrimaryContest[] => {
    if (contested.has(groupKey)) return [];
    const seats = seatsOf(group.office, group.district);
    if (group.names.length > seats) fail(`UNCONTESTED_OVERFILLED:${groupKey}`);
    // Two nominees for a two-seat district cannot be reported as uncounted contests (one nominee each); see above.
    if (group.names.length !== 1) return [];
    return [{ office: group.office, district: group.district, rawParty: group.party, seats, candidates: [{ name: group.names[0]!, votes: null, winner: true }] }];
  });
}

function parse(bytes: Buffer, source: StateGeneralSource, readSource: (sourceId: string) => Buffer): RawPrimaryContest[] {
  if (source.id === CANVASS) return parseCanvass(bytes.toString("utf8"));
  if (source.id !== CANDIDATE_LIST) return fail(`SOURCE_UNKNOWN:${source.id}`);
  const contested = new Set(parseCanvass(readSource(CANVASS).toString("utf8")).map((contest) => key(contest.office, contest.district, contest.rawParty!)));
  return parseCandidateList(bytes.toString("utf8"), contested);
}

export const SOUTH_DAKOTA_PRIMARY: StatePrimaryAdapter = {
  stateCode: "SD",
  authority: "South Dakota Secretary of State, official primary canvass and candidate list",
  system: "partisan",
  sources: SOURCES,
  expectedContests: { [CANVASS]: 53, [CANDIDATE_LIST]: 52 },
  parse,
};
